items.text:
array set props { type function access public }
set error_message ""
set parameters {}

set sections { header footer }
unpack [ gen::scan_file_description $db $sections ] \
header footer

set fhandle [ open_output_file $filename ]

catch {
	print_to_file $fhandle $functions \
		$header $footer $machine_decl $machine_ctrs
} error_message

catch { close $fhandle }

set diagrams [ $gdb eval {
	select diagram_id
	from vertices
	group by diagram_id
} ]

variable variables
variable handlers
set variables {}
set handlers {}

unpack [ $gdb eval { 
	select text, item_id
	from vertices
	where vertex_id = :vertex_id
} ] text item_id

$gdb eval {
	update vertices
	set text = :new_text
	where vertex_id = :vertex_id
}

$gdb eval {
	select diagram_id, original, name
	from diagrams
	where original is not null
} {
	set sm_name $original
	set new_name "${sm_name}_$name"
	$gdb eval {
		update diagrams
		set name = :new_name
		where diagram_id = :diagram_id
	}
	lappend ids $new_name
}
